const LOGO_B64 = "";

const SAR_HTML = '<img src="data:image/png;base64," style="height:.85em;width:auto;vertical-align:middle;margin-right:.1em;display:inline-block" aria-label="ريال سعودي">';
function fmt(v) {
  const r = Math.round(v * 100) / 100;
  const dec = (r % 1) !== 0;
  return r.toLocaleString('en-US', {
    minimumFractionDigits: dec ? ((r * 10 % 1 !== 0) ? 2 : 1) : 0,
    maximumFractionDigits: 2
  }) + ' ' + SAR_HTML;
}

function buildQuotationHTML(data) {
  const {
    client = '', company = '', project = '', salesRep = '',
    quoteNo = 'Q-001',
    date = new Date().toISOString().split('T')[0],
    items = [],
    discount = 0,
    vat = true,
    techNotes = '',
    terms = '',
    validity = ''
  } = data;

  const subtotal     = items.reduce((s, it) => s + (it.unitPrice * it.qty), 0);
  const discountAmt  = subtotal * (discount / 100);
  const afterDisc    = subtotal - discountAmt;
  const vatAmt       = vat ? afterDisc * 0.15 : 0;
  const grand        = afterDisc + vatAmt;

  const rows = items.map((it, i) => `
    <tr>
      <td class="tc num">${i + 1}</td>
      <td class="tc"><span class="code-tag">${it.code}</span></td>
      <td class="tc pic">
        ${it.imageUrl
          ? `<img src="${it.imageUrl}" alt="${it.code}" onerror="this.style.display='none'">`
          : `<div class="ph">📦</div>`}
      </td>
      <td class="td-desc"><div class="desc">${it.desc || ''}</div></td>
      <td class="tc price">${fmt(it.unitPrice)}</td>
      <td class="tc qty">${it.qty}</td>
      <td class="tc total">${fmt(it.unitPrice * it.qty)}</td>
    </tr>`).join('');

  const discountRows = discount > 0 ? `
    <tr class="tot-row">
      <td class="tot-lbl">خصم ${discount}% / Discount</td>
      <td class="tot-val red">(${fmt(discountAmt)})</td>
    </tr>
    <tr class="tot-row">
      <td class="tot-lbl">بعد الخصم / After Discount</td>
      <td class="tot-val">${fmt(afterDisc)}</td>
    </tr>` : '';

  const vatRow = vat ? `
    <tr class="tot-row">
      <td class="tot-lbl">ضريبة 15% / VAT</td>
      <td class="tot-val">${fmt(vatAmt)}</td>
    </tr>` : '';

  return `<!DOCTYPE html>
<html lang="ar" dir="rtl">
<head>
<meta charset="UTF-8">
<title>عرض سعر ${quoteNo}</title>
<style>
*{margin:0;padding:0;box-sizing:border-box;}
html{position:relative;}
body{font-family:'Times New Roman',serif;color:#1c1c1c;background:white;direction:rtl;padding-bottom:2.5cm;position:relative;}
body::before{content:'';position:fixed;top:0;left:0;right:0;bottom:0;background-image:url('data:image/png;base64,${LOGO_B64}');background-size:40%;background-position:center;background-repeat:no-repeat;opacity:.05;pointer-events:none;z-index:-1;}

/* ── PAGE BORDER ── */
body::after{content:'';position:fixed;top:.8cm;left:.8cm;right:.8cm;bottom:.8cm;border:3px solid #0D4A2E;pointer-events:none;z-index:100;}
@page{margin:1cm;margin-bottom:1.7cm;size:A4 portrait;}

/* ── TABLE ── */
table{width:100%;border-collapse:collapse;font-size:.82rem;margin-top:1cm;}
thead tr{background:#0D4A2E;color:white;}
thead th{padding:.55rem .65rem;font-size:.71rem;font-weight:700;text-align:center;border-left:1px solid rgba(255,255,255,.12);white-space:nowrap;}
thead th:last-child{border-left:none;}
thead th.th-desc{text-align:right;}
tbody tr{border-bottom:1px solid #eaeaea;}
tbody td{padding:.5rem .65rem;border-left:1px solid #eaeaea;vertical-align:middle;background:transparent;}
tbody td:last-child{border-left:none;}
.tc{text-align:center;}
.num{color:#999;font-weight:700;font-size:.75rem;width:28px;}
.pic{width:68px;}
.pic img{width:60px;height:60px;object-fit:contain;border-radius:5px;border:1px solid #eee;display:block;margin:0 auto;}
.ph{width:60px;height:60px;border-radius:5px;background:#f5f5f5;display:flex;align-items:center;justify-content:center;font-size:1.3rem;margin:0 auto;border:1px solid #eee;}
.code-tag{display:inline-block;font-size:.7rem;font-weight:800;color:#8A6F2C;border:none!important;background:transparent!important;box-shadow:none!important;padding:.18rem .55rem;border-radius:0;white-space:nowrap;min-width:65px;text-align:center;}
.td-desc{text-align:right;}
.desc{font-size:.8rem;font-weight:600;line-height:1.5;word-break:break-word;}
.price{font-weight:700;color:#1a1a1a;}
.qty{font-weight:700;color:#1a6b6b;}
.total{font-weight:800;color:#1a1a1a;}

/* ── TOTALS ── */
.totals-wrap{display:flex;justify-content:flex-end;padding:.6cm 1cm .4cm;}
.totals-table{width:320px;border:1.5px solid #dde1e7;border-radius:8px;overflow:hidden;}
.totals-table table{font-size:.82rem;margin-top:0;}
.tot-row td{padding:.4rem .85rem;border-bottom:1px solid #eaeaea;}
.tot-row:last-child td{border-bottom:none;}
.tot-lbl{text-align:right;color:#888;font-weight:600;font-size:.78rem;}
.tot-val{text-align:left;font-weight:800;color:#1a1a1a;white-space:nowrap;}
.tot-val.red{color:#c0392b;}
.grand td{background:#0D4A2E!important;padding:.55rem .85rem!important;border-top:2px solid #C2A04A!important;}
.grand .tot-lbl{color:rgba(255,255,255,.65);}
.grand .tot-val{color:#D8BD72;font-size:1rem;font-weight:900;}

/* ── NOTES ── */
.notes-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem;padding:.3cm 1cm .5cm;}
.nb .lbl{display:block;font-size:.6rem;font-weight:800;color:#888;text-transform:uppercase;letter-spacing:.04em;margin-bottom:.22rem;}
.nb .val{font-size:.79rem;line-height:1.65;white-space:pre-wrap;color:#1a1a1a;}
.validity{padding:0 1cm .5cm;}
.validity .lbl{display:block;font-size:.6rem;font-weight:800;color:#888;text-transform:uppercase;letter-spacing:.04em;margin-bottom:.15rem;}
.validity .val{font-size:.82rem;font-weight:600;}

/* ── PRINT FOOTER ── */
.footer{
  position:fixed;bottom:0;left:0;right:0;height:.9cm;
  background:#0D4A2E;display:flex;align-items:center;
  justify-content:space-between;padding:0 1cm;
  color:white;font-size:8pt;font-weight:600;
  -webkit-print-color-adjust:exact;print-color-adjust:exact;
}
</style>
</head>
<body>

<table>
  <thead>
    <tr>
      <th style="width:28px">#</th>
      <th style="width:90px">الصنف</th>
      <th style="width:70px">صورة</th>
      <th class="th-desc">الوصف / Description</th>
      <th style="width:105px">سعر الوحدة</th>
      <th style="width:48px">الكمية</th>
      <th style="width:130px">الإجمالي</th>
    </tr>
  </thead>
  <tbody>
    ${rows || '<tr><td colspan="7" style="text-align:center;padding:2rem;color:#888">لا توجد بنود</td></tr>'}
  </tbody>
</table>

<div class="totals-wrap">
  <div class="totals-table">
    <table>
      <tr class="tot-row">
        <td class="tot-lbl">المجموع / Subtotal</td>
        <td class="tot-val">${fmt(subtotal)}</td>
      </tr>
      ${discountRows}
      ${vatRow}
      <tr class="grand">
        <td class="tot-lbl">الإجمالي الكلي / Grand Total</td>
        <td class="tot-val">${fmt(grand)}</td>
      </tr>
    </table>
  </div>
</div>

${(techNotes || terms) ? `
<div class="notes-grid">
  ${techNotes ? `<div class="nb"><span class="lbl">الملاحظات الفنية / Technical Notes</span><div class="val">${techNotes}</div></div>` : '<div></div>'}
  ${terms ? `<div class="nb"><span class="lbl">الشروط والأحكام / Terms & Conditions</span><div class="val">${terms}</div></div>` : ''}
</div>` : ''}

${validity ? `<div class="validity"><span class="lbl">صلاحية العرض / Validity</span><div class="val">${validity}</div></div>` : ''}

<div class="footer">
  <div style="display:flex;align-items:center;gap:8px;"><span style="font-size:8pt;font-weight:800;letter-spacing:.03em">المدى المبارك</span><span style="opacity:.6;font-size:7pt">للتجارة والحلول الذكية</span></div>
  <div>صفحة 1</div>
  <div style="direction:ltr">+966 50 000 0000</div>
</div>

</body>
</html>`;
}

module.exports = { buildQuotationHTML };
